def max_Product(arr):
    # Handle edge cases
    if len(arr) < 2:
        return None  # Not enough elements for a pair

    # Initialize variables to track the two largest and two smallest numbers
    max1 = max2 = float('-inf')  # Two largest numbers
    min1 = min2 = float('inf')   # Two smallest numbers

    # Iterate through the array to find the two largest and two smallest numbers
    for num in arr:
        # Update the two largest numbers
        if num > max1:
            max2, max1 = max1, num
        elif num > max2:
            max2 = num

        # Update the two smallest numbers
        if num < min1:
            min2, min1 = min1, num
        elif num < min2:
            min2 = num

    # Compare the products of the two largest and two smallest numbers
    if max1 * max2 > min1 * min2:
        return (max2, max1)  # Return the pair in ascending order
    else:
        return (min1, min2)  # Return the pair in ascending order
